window.SAOMD_STORIES[410401601]={"id":410401601,"branches":[],"frames":[{"id":1,"order":1,"actions":[{"uid":"410401601:1:1","speaker":"???","text":"I am Odin, lord of Asgard.","pose":20380105,"background":"bg_12_church_room","item":"","illustration":"","speaker_zh":"？？？","text_zh":"我是奥丁，阿斯加德之主。"},{"uid":"410401601:1:2","speaker":"???","text":"","pose":20400105,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":""},{"uid":"410401601:1:3","speaker":"???","text":"","pose":20390105,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":""}]},{"id":2,"order":2,"actions":[{"uid":"410401601:2:1","speaker":"???","text":"I am Freyja, god of beauty...\nIt falls to me to restore the\nworld to its natural splendor.","pose":20400105,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"我是芙蕾雅，美神……让世界恢复自然光彩的任务就落在我身上了。"}]},{"id":3,"order":3,"actions":[{"uid":"410401601:3:1","speaker":"???","text":"I am Tyr, god of war. Where is the\nnearest field of battle, that I\nmay quench my bloodlust?","pose":20390105,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"我是战神提尔。最近的战场在哪里，可以让我平息我的嗜血欲望？"},{"uid":"410401601:3:2","speaker":"???","text":"","pose":20400105,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":""}]},{"id":4,"order":4,"actions":[{"uid":"410401601:4:1","speaker":"???","text":"I'm Hel, god of death. You're all\nwelcome to visit me in Helheim\nwhenever you like.","pose":20410105,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"我是死神赫尔。欢迎大家随时来赫尔海姆拜访我。"},{"uid":"410401601:4:2","speaker":"???","text":"","pose":20420105,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":""}]},{"id":5,"order":5,"actions":[{"uid":"410401601:5:1","speaker":"???","text":"My name's Loki. I can tell this is\ngoing to be fun.","pose":20420105,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"我叫洛基。我可以说这会很有趣。"}]},{"id":6,"order":6,"actions":[{"uid":"410401601:6:1","speaker":"Kirito","text":"Wh-What is all this?","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"这、这是什么？"},{"uid":"410401601:6:2","speaker":"Leafa","text":"","pose":10030104,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""},{"uid":"410401601:6:3","speaker":"Asuna","text":"","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":7,"order":7,"actions":[{"uid":"410401601:7:1","speaker":"Leafa","text":"I recognize those names!\nThey're all famous gods from\nNorse mythology!","pose":10030104,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"我认得这些名字！他们都是北欧神话中赫赫有名的神祇！"}]},{"id":8,"order":8,"actions":[{"uid":"410401601:8:1","speaker":"Asuna","text":"Uh, Leafa, I'm not sure now's the\nbest time for a dissertation!","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"呃，莉法，我不知道现在是不是写论文的最佳时机！"}]},{"id":9,"order":9,"actions":[{"uid":"410401601:9:1","speaker":"Leafa","text":"Oh, sorry!","pose":10030108,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"哦，对不起！"}]},{"id":10,"order":10,"actions":[{"uid":"410401601:10:1","speaker":"Alice","text":"They're gods? I don't understand.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"他们是神？我不明白。"},{"uid":"410401601:10:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":11,"order":11,"actions":[{"uid":"410401601:11:1","speaker":"Alice","text":"The force they exude is more akin\nto the beasts lured in by the\nDivine Objects.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"它们散发出的力量，更像是被神器引诱过来的野兽。"}]},{"id":12,"order":12,"actions":[{"uid":"410401601:12:1","speaker":"Eugeo","text":"I agree. The sheer hostility I\nsense from them is just like the\nDivine Objects' monsters.","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我同意。我从他们身上感受到的纯粹的敌意就像神器的怪物一样。"},{"uid":"410401601:12:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":13,"order":13,"actions":[{"uid":"410401601:13:1","speaker":"Urdr","text":"But of course. We six gods,\nmyself included...","pose":20330205,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"但是当然。我们六位神，包括我自己……"}]},{"id":14,"order":14,"actions":[{"uid":"410401601:14:1","speaker":"Urdr","text":"...used the Objects as a catalyst\nto restore ourselves to life.","pose":20330205,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"……用这些物品作为催化剂让我们复活。"}]},{"id":15,"order":15,"actions":[{"uid":"410401601:15:1","speaker":"Kirito","text":"A catalyst...?","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"催化剂……？"},{"uid":"410401601:15:2","speaker":"Leafa","text":"","pose":10030108,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""},{"uid":"410401601:15:3","speaker":"Asuna","text":"","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":16,"order":16,"actions":[{"uid":"410401601:16:1","speaker":"Asuna","text":"Hey, the Divine Objects...\nAll six of them are gone!","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"哎呀，神器……六个都没有了！"}]},{"id":17,"order":17,"actions":[{"uid":"410401601:17:1","speaker":"Kirito","text":"So, the Objects actually turned\ninto the Norse gods?!","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"原来Objects真的变成了北欧诸神？！"},{"uid":"410401601:17:2","speaker":"Asuna","text":"","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":18,"order":18,"actions":[{"uid":"410401601:18:1","speaker":"Urdr","text":"Now, my companions, let us\neliminate these pests and begin\ncleansing this world.","pose":20330207,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"现在，我的同伴们，让我们消灭这些害虫，开始净化这个世界。"}]},{"id":19,"order":19,"actions":[{"uid":"410401601:19:1","speaker":"Odin","text":"What lowly fools dare to defy the\ngods?","pose":20380101,"background":"","item":"","illustration":"","speaker_zh":"奥丁","text_zh":"什么卑贱的蠢货敢反抗神明？"},{"uid":"410401601:19:2","speaker":"Freyja","text":"","pose":20400105,"background":"","item":"","illustration":"","speaker_zh":"芙蕾雅","text_zh":""},{"uid":"410401601:19:3","speaker":"Tyr","text":"","pose":20390105,"background":"","item":"","illustration":"","speaker_zh":"提尔","text_zh":""}]},{"id":20,"order":20,"actions":[{"uid":"410401601:20:1","speaker":"Tyr","text":"Excellent! Let the battle\ncommence!","pose":20390105,"background":"","item":"","illustration":"","speaker_zh":"提尔","text_zh":"太好了！让战斗开始吧！"}]},{"id":21,"order":21,"actions":[{"uid":"410401601:21:1","speaker":"Kirito","text":"Uh oh... Looks like we have no\nchoice but to fight!","pose":10011501,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"呃哦……看来我们只能战斗了！"},{"uid":"410401601:21:2","speaker":"Leafa","text":"","pose":10030101,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""},{"uid":"410401601:21:3","speaker":"Asuna","text":"","pose":10020901,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":22,"order":22,"actions":[{"uid":"410401601:22:1","speaker":"Kirito","text":"Argh! Damn it!","pose":10011508,"background":"bg_event_fire_cave","item":"","illustration":"","speaker_zh":"桐人","text_zh":"啊！该死的！"},{"uid":"410401601:22:2","speaker":"Asuna","text":"","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401601:22:3","speaker":"Leafa","text":"","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":23,"order":23,"actions":[{"uid":"410401601:23:1","speaker":"Asuna","text":"K-Kirito? Are you alive?","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"K-桐人？你还活着吗？"}]},{"id":24,"order":24,"actions":[{"uid":"410401601:24:1","speaker":"Kirito","text":"Just barely. I really thought we\nwere done for this time...","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"勉强可以。我真的以为我们这次就完蛋了……"}]},{"id":25,"order":25,"actions":[{"uid":"410401601:25:1","speaker":"Asuna","text":"Thank goodness we were all able to\nescape...","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"谢天谢地我们都逃出来了……"},{"uid":"410401601:25:2","speaker":"Leafa","text":"","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":26,"order":26,"actions":[{"uid":"410401601:26:1","speaker":"Alice","text":"Who were those people? They\nclaimed to be gods, yet they\nexuded pure evil. What's more...","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"那些人是谁？他们自称是神，却散发着纯粹的邪恶。更何况..."},{"uid":"410401601:26:2","speaker":"Eugeo","text":"","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":27,"order":27,"actions":[{"uid":"410401601:27:1","speaker":"Eugeo","text":"Yeah... They were horrifically\nstrong. I don't know if we'd stand\na chance against even one of them.","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"是啊……他们强得可怕。我不知道我们是否有机会对抗他们中的任何一个。"}]},{"id":28,"order":28,"actions":[{"uid":"410401601:28:1","speaker":"Leafa","text":"No wonder they're so renowned in\nNorse mythology. Compared to\nfairies like us...","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"难怪他们在北欧神话中如此出名。和我们这些小仙女相比……"},{"uid":"410401601:28:2","speaker":"Kirito","text":"","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401601:28:3","speaker":"Asuna","text":"","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":29,"order":29,"actions":[{"uid":"410401601:29:1","speaker":"Kirito","text":"Yeah. Even I've at least heard all\nthose names before.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯。即使我以前至少听说过所有这些名字。"}]},{"id":30,"order":30,"actions":[{"uid":"410401601:30:1","speaker":"Kirito","text":"Back when we fought Thrymr, he\nsaid something about not trusting\nthe gods...","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"当初我们和Thrymr战斗的时候，他说过一些关于不相信神的话……"}]},{"id":31,"order":31,"actions":[{"uid":"410401601:31:1","speaker":"Kirito","text":"Maybe this is what he meant?\nI never thought Urdr would do\nsomething like that...","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"也许他就是这个意思？我没想到乌尔德会做出这样的事......"}]},{"id":32,"order":32,"actions":[{"uid":"410401601:32:1","speaker":"Leafa","text":"I don't think that's it. I mean,\nthere was just something totally\nstrange about those gods.","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"我不认为是这样。我的意思是，那些神有一些完全奇怪的东西。"}]},{"id":33,"order":33,"actions":[{"uid":"410401601:33:1","speaker":"Asuna","text":"What's that?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"那是什么？"}]},{"id":34,"order":34,"actions":[{"uid":"410401601:34:1","speaker":"Leafa","text":"Odin, Tyr, Freyja...","pose":10030107,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"奥丁、提尔、芙蕾雅..."}]},{"id":35,"order":35,"actions":[{"uid":"410401601:35:1","speaker":"Leafa","text":"These are all\nnames that have already been used\nin other parts of ALO.","pose":10030107,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"这些都是ALO其他部分已经使用过的名称。"}]},{"id":36,"order":36,"actions":[{"uid":"410401601:36:1","speaker":"Kirito","text":"Yeah... You're right! Freyja was\nthe woman Thrymr turned himself\ninto, wasn't she?","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是啊……你说得对！ 芙蕾雅就是 Thrymr 把自己变成的女人，不是吗？"}]},{"id":37,"order":37,"actions":[{"uid":"410401601:37:1","speaker":"Leafa","text":"Yup. Which means all those\nelements that were used before are\nbeing repurposed for this story.","pose":10030107,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"是的。这意味着之前使用的所有元素都将被重新用于这个故事。"}]},{"id":38,"order":38,"actions":[{"uid":"410401601:38:1","speaker":"Leafa","text":"Basically, the Cardinal System\nmust have made them after the fact\nfor the Divine Objects quest.","pose":10030107,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"基本上，卡迪纳尔系统一定是为了神器任务而事后制作的。"}]},{"id":39,"order":39,"actions":[{"uid":"410401601:39:1","speaker":"Kirito","text":"Which would mean this quest is\nunique to us, and has no bearing\non ALO at large.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"也就是说这个任务是我们独有的，与ALO没有任何关系。"}]},{"id":40,"order":40,"actions":[{"uid":"410401601:40:1","speaker":"Leafa","text":"I think so too.","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"我也这么认为。"}]},{"id":41,"order":41,"actions":[{"uid":"410401601:41:1","speaker":"Alice","text":"What are you two talking about?","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"你们两个在说什么？"},{"uid":"410401601:41:2","speaker":"Eugeo","text":"","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":42,"order":42,"actions":[{"uid":"410401601:42:1","speaker":"Kirito","text":"Oh, sorry guys.\nI guess this must be kind of\ntough for you to follow.","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哦，对不起。我想这对你来说一定很难理解。"},{"uid":"410401601:42:2","speaker":"Leafa","text":"","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""},{"uid":"410401601:42:3","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":43,"order":43,"actions":[{"uid":"410401601:43:1","speaker":"Alice","text":"I've grown used to your cryptic\ntalk by now. More importantly,\ndoes this mean Urdr set us up?","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我已经习惯你的晦涩难懂了。更重要的是，这是否意味着乌尔德陷害了我们？"},{"uid":"410401601:43:2","speaker":"Eugeo","text":"","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":44,"order":44,"actions":[{"uid":"410401601:44:1","speaker":"Kirito","text":"Well...","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯……"},{"uid":"410401601:44:2","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401601:44:3","speaker":"Leafa","text":"","pose":10030107,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":45,"order":45,"actions":[{"uid":"410401601:45:1","speaker":"Eugeo","text":"If she did, it would mean she was\nusing us to collect the Divine\nObjects for her from the get-go.","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"如果她这么做了，那就说明她一开始就是利用我们来为她收集神器的。"},{"uid":"410401601:45:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":46,"order":46,"actions":[{"uid":"410401601:46:1","speaker":"Alice","text":"That goddess must answer for what\nshe's done.","pose":10540101,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"女神必须为自己的所作所为负责。"}]},{"id":47,"order":47,"actions":[{"uid":"410401601:47:1","speaker":"Kirito","text":"...","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"..."},{"uid":"410401601:47:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401601:47:3","speaker":"Leafa","text":"","pose":10030107,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":48,"order":48,"actions":[{"uid":"410401601:48:1","speaker":"Asuna","text":"Looks like Alice and Eugeo fell\nasleep again.","pose":10020902,"background":"bg_11_home_lounge","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"看来爱丽丝和尤吉欧又睡着了。"}]},{"id":49,"order":49,"actions":[{"uid":"410401601:49:1","speaker":"Kirito","text":"I guess we have been through a\nlot. I can't blame them for being\nexhausted.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我想我们经历了很多。我不能责怪他们精疲力尽。"}]},{"id":50,"order":50,"actions":[{"uid":"410401601:50:1","speaker":"Asuna","text":"Still... I don't know how we're\ngoing to explain to them what\nprobably happened with Urdr.","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"还是……我不知道如何向他们解释乌尔德可能发生的事情。"}]},{"id":51,"order":51,"actions":[{"uid":"410401601:51:1","speaker":"Asuna","text":"I mean, the Cardinal System\nspontaneously turning an NPC\ngoddess into this quest's boss?","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我的意思是，卡迪纳尔系统自发地将NPC女神变成了这个任务的首领？"}]},{"id":52,"order":52,"actions":[{"uid":"410401601:52:1","speaker":"Asuna","text":"Where would we even begin?","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我们从哪里开始呢？"}]},{"id":53,"order":53,"actions":[{"uid":"410401601:53:1","speaker":"Leafa","text":"True. Urdr was definitely a good\nNPC when we first met her.","pose":10030107,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"是的。当我们第一次见到她时，乌尔德绝对是一个很好的NPC。"}]},{"id":54,"order":54,"actions":[{"uid":"410401601:54:1","speaker":"Kirito","text":"But then the Cardinal System went\nand made her into a villain...","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"但是后来卡迪纳尔系统把她变成了反派……"}]},{"id":55,"order":55,"actions":[{"uid":"410401601:55:1","speaker":"Kirito","text":"I told Alice and Eugeo that she's\njust being controlled by the\nObjects, but they didn't buy it.","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我告诉爱丽丝和尤吉欧她只是被物体控制了，但他们不买账。"}]},{"id":56,"order":56,"actions":[{"uid":"410401601:56:1","speaker":"Asuna","text":"Anyway, we still need to figure\nout what to do.","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"不管怎样，我们还是得想办法做什么。"}]},{"id":57,"order":57,"actions":[{"uid":"410401601:57:1","speaker":"Asuna","text":"I doubt those six gods are just\ngoing to stay put in Jotunheimr\nwithout making trouble.","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我怀疑那六位大神是不是会留在幽兹海姆不闹事。"}]},{"id":58,"order":58,"actions":[{"uid":"410401601:58:1","speaker":"Leafa","text":"Yeah... Not to mention how they\nwere talking about cleansing the\nworld and whatnot.","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"是啊……更不用说他们是如何谈论净化世界之类的了。"},{"uid":"410401601:58:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401601:58:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":59,"order":59,"actions":[{"uid":"410401601:59:1","speaker":"Yui","text":"Everyone!\nWe have a big problem!","pose":20090208,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"大家！我们有一个大问题！"}]},{"id":60,"order":60,"actions":[{"uid":"410401601:60:1","speaker":"Kirito","text":"What is it, Yui?","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"结衣，是什么？"},{"uid":"410401601:60:2","speaker":"Leafa","text":"","pose":10030105,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""},{"uid":"410401601:60:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":61,"order":61,"actions":[{"uid":"410401601:61:1","speaker":"Yui","text":"Look at this!","pose":20090201,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"看这个！"}]},{"id":62,"order":62,"actions":[{"uid":"410401601:62:1","speaker":"Yui","text":"Remember how you had Sinon and the\nothers traversing ALO in search of\nthe Divine Objects?","pose":20090206,"background":"bg_11_home_lounge","item":"","illustration":"","speaker_zh":"结衣","text_zh":"还记得诗乃和其他人是如何穿越ALO寻找神器的吗？"},{"uid":"410401601:62:2","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":63,"order":63,"actions":[{"uid":"410401601:63:1","speaker":"Kirito","text":"Uh huh. I knew you would do a\ngreat job of sifting through all\nthe information for us.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯嗯。我知道您会为我们出色地筛选所有信息。"}]},{"id":64,"order":64,"actions":[{"uid":"410401601:64:1","speaker":"Yui","text":"Well, I just heard back from all\nof them nearly simultaneously,\nboth text and visuals!","pose":20090206,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"好吧，我几乎同时收到了他们所有人的回复，包括文字和图像！"}]},{"id":65,"order":65,"actions":[{"uid":"410401601:65:1","speaker":"Kirito","text":"What is this...?","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"这是什么……？"}]},{"id":66,"order":66,"actions":[{"uid":"410401601:66:1","speaker":"Leafa","text":"This is from Sinon and Silica...\nIt looks like Odin's destroying\nthings in Cait Sith territory!","pose":10030108,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"这是来自诗乃和西莉卡的……看来是奥丁在猫妖领地里破坏了东西！"},{"uid":"410401601:66:2","speaker":"Asuna","text":"","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":67,"order":67,"actions":[{"uid":"410401601:67:1","speaker":"Asuna","text":"And this video from Liz and Rain\nshows Freyja attacking other\nfairies in the Leprechaun area!","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"莉兹和蕾茵的这段视频显示芙蕾雅正在攻击小矮妖区域的其他妖精！"}]},{"id":68,"order":68,"actions":[{"uid":"410401601:68:1","speaker":"Kirito","text":"Klein sent us a photo of Hel in\nSalamander territory...","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"克莱因给我们发了一张赫尔在火精灵领地的照片..."},{"uid":"410401601:68:2","speaker":"Yui","text":"","pose":20090206,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":69,"order":69,"actions":[{"uid":"410401601:69:1","speaker":"Kirito","text":"According to Agil and Strea,\nTyr's done a ton of damage in the\nGnome region...","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"根据艾基尔和斯朵蕾雅，提尔在大地精灵地区造成了大量伤害……"}]},{"id":70,"order":70,"actions":[{"uid":"410401601:70:1","speaker":"Asuna","text":"And thanks to Yuuki, we know\nthat Loki's making trouble in\nthe Imp zone.","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"感谢优纪，我们知道洛基在Imp区闹事。"},{"uid":"410401601:70:2","speaker":"Leafa","text":"","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":71,"order":71,"actions":[{"uid":"410401601:71:1","speaker":"Leafa","text":"So they really did launch an\nattack on the surface world...","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"所以他们确实对地表世界发起了攻击……"}]},{"id":72,"order":72,"actions":[{"uid":"410401601:72:1","speaker":"Asuna","text":"Hey... This message\nis from Sphica.","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"嘿……这条消息来自丝菲卡。"}]},{"id":73,"order":73,"actions":[{"uid":"410401601:73:1","speaker":"Asuna","text":"She said she was going to\nUndine territory to see Feliz...","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"她说要去水精灵领地看Feliz……"}]},{"id":74,"order":74,"actions":[{"uid":"410401601:74:1","speaker":"Asuna","text":"...","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"..."}]},{"id":75,"order":75,"actions":[{"uid":"410401601:75:1","speaker":"Asuna","text":"And it looks like Urdr herself is\nthe one attacking it...","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"而且看来攻击它的是乌尔德自己……"}]},{"id":76,"order":76,"actions":[{"uid":"410401601:76:1","speaker":"Kirito","text":"So they've all split up... Are\nthey just trying to destroy the\nsurface? Or maybe...","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"所以他们都分裂了……他们只是想破坏地表吗？或者也许..."},{"uid":"410401601:76:2","speaker":"Yui","text":"","pose":20090206,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":77,"order":77,"actions":[{"uid":"410401601:77:1","speaker":"Asuna","text":"We can figure that out later.\nRight now, we need to go and help\neveryone!","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"这个我们稍后再解决。现在，我们需要去帮助大家！"},{"uid":"410401601:77:2","speaker":"Leafa","text":"","pose":10030106,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":78,"order":78,"actions":[{"uid":"410401601:78:1","speaker":"Yui","text":"What do we do, Mommy? Should we\nsplit up ourselves, so we can take\nthem all on at once?","pose":20090207,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"妈妈，我们该怎么办？我们是否应该分开，这样我们就可以同时对付他们了？"},{"uid":"410401601:78:2","speaker":"Kirito","text":"","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":79,"order":79,"actions":[{"uid":"410401601:79:1","speaker":"Asuna","text":"I'm not sure...","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我不确定……"},{"uid":"410401601:79:2","speaker":"Leafa","text":"","pose":10030107,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":80,"order":80,"actions":[{"uid":"410401601:80:1","speaker":"Leafa","text":"Kazuto, you and Asuna should go to\nthe Undine area.","pose":10030107,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"和人，你和亚丝娜应该去水精灵区域。"}]},{"id":81,"order":81,"actions":[{"uid":"410401601:81:1","speaker":"Leafa","text":"There's no way Sphica and Feliz\ncan handle a Divine Object god on\ntheir own.","pose":10030107,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"丝菲卡和Feliz无法单独对付神器神。"}]},{"id":82,"order":82,"actions":[{"uid":"410401601:82:1","speaker":"Asuna","text":"What about you, Leafa?","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"莉法，你呢？"}]},{"id":83,"order":83,"actions":[{"uid":"410401601:83:1","speaker":"Leafa","text":"Yuuki's fighting all by herself\nright now, so I'm gonna go to the\nImp area to help her.","pose":10030105,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"优纪现在一个人在战斗，我要去小鬼区帮助她。"}]},{"id":84,"order":84,"actions":[{"uid":"410401601:84:1","speaker":"Leafa","text":"Klein's fighting all by himself\ntoo, but Salamanders are pretty\ntough, so they should manage.","pose":10030105,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"克莱因也是一个人在战斗，不过火蜥蜴很厉害，应该能应付。"}]},{"id":85,"order":85,"actions":[{"uid":"410401601:85:1","speaker":"Kirito","text":"Good point. Okay, let's do it.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"说得好。好吧，我们开始吧。"},{"uid":"410401601:85:2","speaker":"Yui","text":"","pose":20090207,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":86,"order":86,"actions":[{"uid":"410401601:86:1","speaker":"Asuna","text":"So, what do we do about Alice and\nEugeo?","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"那么，爱丽丝和尤吉欧我们该怎么办呢？"},{"uid":"410401601:86:2","speaker":"Leafa","text":"","pose":10030107,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":87,"order":87,"actions":[{"uid":"410401601:87:1","speaker":"Kirito","text":"They're still asleep, and I'd hate\nto burden them any more... I say\nwe leave them behind this time.","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"他们还在睡觉，我不想再给他们增加负担了……我说这次就抛开他们吧。"},{"uid":"410401601:87:2","speaker":"Yui","text":"","pose":20090207,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":88,"order":88,"actions":[{"uid":"410401601:88:1","speaker":"Asuna","text":"Yeah... I guess that's all we CAN\ndo right now.","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"是啊……我想我们现在能做的就是这些了。"},{"uid":"410401601:88:2","speaker":"Leafa","text":"","pose":10030107,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":89,"order":89,"actions":[{"uid":"410401601:89:1","speaker":"Alice","text":"Eugeo! I can't find the others\nanywhere!","pose":10540108,"background":"bg_11_home_lounge","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"尤吉欧！我到处都找不到其他人！"},{"uid":"410401601:89:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":90,"order":90,"actions":[{"uid":"410401601:90:1","speaker":"Eugeo","text":"I thought as much. Don't worry,\nthey went east. They're most\nlikely headed for Asuna's domain.","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我也是这么想的。别担心，他们往东走。他们很可能前往亚丝娜的域名。"}]},{"id":91,"order":91,"actions":[{"uid":"410401601:91:1","speaker":"Alice","text":"Then let's go after them.\nAnd Eugeo...we are in agreement,\naren't we?","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"那我们去追吧。 尤吉欧...我们意见一致，不是吗？"}]},{"id":92,"order":92,"actions":[{"uid":"410401601:92:1","speaker":"Eugeo","text":"Of course. I'm completely fine\nwith it.","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"当然。我完全同意。"}]},{"id":93,"order":93,"actions":[{"uid":"410401601:93:1","speaker":"Alice","text":"Good. That's all I wanted to hear.\nNow come, let's be on our way.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"好。这就是我想听到的。现在来吧，我们上路吧。"}]},{"id":94,"order":94,"actions":[{"uid":"410401601:94:1","speaker":"Eugeo","text":"Yeah.","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"嗯。"},{"uid":"410401601:94:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":95,"order":95,"actions":[{"uid":"410401601:95:1","speaker":"Undine Player A","text":"S-Somebody help me!","pose":2,"background":"bg_event_temple","item":"","illustration":"","speaker_zh":"水精灵玩家A","text_zh":"谁、谁来救救我！"},{"uid":"410401601:95:2","speaker":"Urdr","text":"","pose":20330205,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":""}]},{"id":96,"order":96,"actions":[{"uid":"410401601:96:1","speaker":"Undine Player B","text":"Can't we all take her together?\nIt's just one giantess.","pose":2,"background":"","item":"","illustration":"","speaker_zh":"水精灵玩家B","text_zh":"我们不能一起带她吗？这只是一位女巨人。"}]},{"id":97,"order":97,"actions":[{"uid":"410401601:97:1","speaker":"Undine Player A","text":"Word has it that she wiped out our\nleader's personal battalion,\nall by herself...","pose":2,"background":"","item":"","illustration":"","speaker_zh":"水精灵玩家A","text_zh":"据说她一个人就消灭了我们首领的私人营……"}]},{"id":98,"order":98,"actions":[{"uid":"410401601:98:1","speaker":"Undine Player B","text":"Seriously?! What's going on?!\nIs this some kind of Ragnarok\nevent?!","pose":2,"background":"","item":"","illustration":"","speaker_zh":"水精灵玩家B","text_zh":"真的吗？！这是怎么回事？！这是某种仙境传说事件吗？！"}]},{"id":99,"order":99,"actions":[{"uid":"410401601:99:1","speaker":"Urdr","text":"It appears...the foreign elements\nare not here...","pose":20330205,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"看来……外国元素不在这里……"}]},{"id":100,"order":100,"actions":[{"uid":"410401601:100:1","speaker":"Sphica","text":"Hey, giant lady! What's the big\nidea wrecking everything?!","pose":10520101,"background":"","item":"","illustration":"","speaker_zh":"丝菲卡","text_zh":"喂，巨女！破坏一切的伟大想法是什么？"},{"uid":"410401601:100:2","speaker":"Feliz","text":"","pose":20360106,"background":"","item":"","illustration":"","speaker_zh":"Feliz","text_zh":""}]},{"id":101,"order":101,"actions":[{"uid":"410401601:101:1","speaker":"Sphica","text":"What'd these people ever do to you\nthat you had go around destroying\ntheir town?!","pose":10520101,"background":"","item":"","illustration":"","speaker_zh":"丝菲卡","text_zh":"这些人对你做了什么，你竟然要毁掉他们的小镇？！"}]},{"id":102,"order":102,"actions":[{"uid":"410401601:102:1","speaker":"Feliz","text":"Come on, Sphica, let's just get\nout of here. There's no way we can\npossibly beat her.","pose":20360106,"background":"","item":"","illustration":"","speaker_zh":"Feliz","text_zh":"走吧，丝菲卡，我们赶紧离开这里吧。我们根本不可能打败她。"}]},{"id":103,"order":103,"actions":[{"uid":"410401601:103:1","speaker":"Sphica","text":"I can't just run away without\ndoing anything!","pose":10520107,"background":"","item":"","illustration":"","speaker_zh":"丝菲卡","text_zh":"我不能什么都不做就跑掉！"}]},{"id":104,"order":104,"actions":[{"uid":"410401601:104:1","speaker":"Sphica","text":"If Asuna was here, she wouldn't\nhesitate to stand up to her!","pose":10520101,"background":"","item":"","illustration":"","speaker_zh":"丝菲卡","text_zh":"如果亚丝娜在这里，她会毫不犹豫地站出来对抗她！"},{"uid":"410401601:104:2","speaker":"Feliz","text":"","pose":20360106,"background":"","item":"","illustration":"","speaker_zh":"Feliz","text_zh":""}]},{"id":105,"order":105,"actions":[{"uid":"410401601:105:1","speaker":"Urdr","text":"Asuna... So, you are friends of\ntheirs.","pose":20330205,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"亚丝娜...所以，你是他们的朋友了。"}]},{"id":106,"order":106,"actions":[{"uid":"410401601:106:1","speaker":"Urdr","text":"Then I shall dispose of you, as a\nwarning to the others.","pose":20330207,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"那我就处理掉你，警告其他人。"}]},{"id":107,"order":107,"actions":[{"uid":"410401601:107:1","speaker":"Sphica","text":"A-Ahhh!","pose":10520101,"background":"","item":"","illustration":"","speaker_zh":"丝菲卡","text_zh":"啊、啊啊！"},{"uid":"410401601:107:2","speaker":"Feliz","text":"","pose":20360108,"background":"","item":"","illustration":"","speaker_zh":"Feliz","text_zh":""}]},{"id":108,"order":108,"actions":[{"uid":"410401601:108:1","speaker":"Feliz","text":"Waaah!","pose":20360108,"background":"","item":"","illustration":"","speaker_zh":"Feliz","text_zh":"哇啊！"}]},{"id":109,"order":109,"actions":[{"uid":"410401601:109:1","speaker":"???","text":"Hold it!","pose":2,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"坚持住！"},{"uid":"410401601:109:2","speaker":"Sphica","text":"","pose":10520108,"background":"","item":"","illustration":"","speaker_zh":"丝菲卡","text_zh":""},{"uid":"410401601:109:3","speaker":"Feliz","text":"","pose":20360108,"background":"","item":"","illustration":"","speaker_zh":"Feliz","text_zh":""}]},{"id":110,"order":110,"actions":[{"uid":"410401601:110:1","speaker":"Urdr","text":"...!","pose":20330207,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"...!"}]},{"id":111,"order":111,"actions":[{"uid":"410401601:111:1","speaker":"Kirito","text":"That's enough, Urdr!","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"够了，乌尔德！"}]},{"id":112,"order":112,"actions":[{"uid":"410401601:112:1","speaker":"Asuna","text":"Urdr, please! Snap out of it!","pose":10020901,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"乌尔德，拜托！快点摆脱它吧！"}]},{"id":113,"order":113,"actions":[{"uid":"410401601:113:1","speaker":"Sphica","text":"Kirito, Asuna! You came to help\nus?!","pose":10520104,"background":"","item":"","illustration":"","speaker_zh":"丝菲卡","text_zh":"桐人，亚丝娜！你是来帮我们的？！"},{"uid":"410401601:113:2","speaker":"Feliz","text":"","pose":20360104,"background":"","item":"","illustration":"","speaker_zh":"Feliz","text_zh":""}]},{"id":114,"order":114,"actions":[{"uid":"410401601:114:1","speaker":"Asuna","text":"Of course we did! Now go hide,\nquickly!","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"当然有！现在赶紧躲起来吧！"},{"uid":"410401601:114:2","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":115,"order":115,"actions":[{"uid":"410401601:115:1","speaker":"Sphica","text":"Don't gotta tell me twice!","pose":10520104,"background":"","item":"","illustration":"","speaker_zh":"丝菲卡","text_zh":"别告诉我两次！"},{"uid":"410401601:115:2","speaker":"Feliz","text":"","pose":20360104,"background":"","item":"","illustration":"","speaker_zh":"Feliz","text_zh":""}]},{"id":116,"order":116,"actions":[{"uid":"410401601:116:1","speaker":"Urdr","text":"There you are, brave warriors.\nYet I do not see those foreign\nelements...","pose":20330205,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"你们来了，勇敢的战士们。但我没有看到那些外国元素......"}]},{"id":117,"order":117,"actions":[{"uid":"410401601:117:1","speaker":"Kirito","text":"Foreign elements...? Are you\ntalking about Alice and Eugeo?","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"外国元素……？您是在谈论爱丽丝和尤吉欧吗？"},{"uid":"410401601:117:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":118,"order":118,"actions":[{"uid":"410401601:118:1","speaker":"Urdr","text":"The two who address me as\n\"goddess of this realm.\"","pose":20330207,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"称呼我为“这个领域的女神”的两人。"}]},{"id":119,"order":119,"actions":[{"uid":"410401601:119:1","speaker":"Urdr","text":"Now, bring them here at once.\nI must eliminate them.","pose":20330207,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"现在，立刻把他们带到这里来。我必须消灭他们。"}]},{"id":120,"order":120,"actions":[{"uid":"410401601:120:1","speaker":"Kirito","text":"Why are you doing this? They're\nthe ones you asked to collect the\nObjects in the first place, right?","pose":10011501,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"你为什么要这么做？他们是你首先要求收集物品的人，对吗？"},{"uid":"410401601:120:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":121,"order":121,"actions":[{"uid":"410401601:121:1","speaker":"Urdr","text":"...The Divine Objects never\nbelonged to this world.","pose":20330205,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"……神器从来不属于这个世界。"}]},{"id":122,"order":122,"actions":[{"uid":"410401601:122:1","speaker":"Urdr","text":"They appeared when those two did,\nyet felt as if they had been here\nsince the days of the ancients.","pose":20330205,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"他们和那两个人同时出现，却又仿佛自古以来就在这里了。"}]},{"id":123,"order":123,"actions":[{"uid":"410401601:123:1","speaker":"Urdr","text":"It took me some time to realize\nthat the Divine Objects were just\nas foreign as your two friends.","pose":20330205,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"我花了一些时间才意识到神器和你的两个朋友一样陌生。"}]},{"id":124,"order":124,"actions":[{"uid":"410401601:124:1","speaker":"Urdr","text":"And yet, it was they that brought\ndisaster upon us. The world\nchanged when they appeared.","pose":20330205,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"然而，却是他们给我们带来了灾难。当他们出现时，世界就改变了。"}]},{"id":125,"order":125,"actions":[{"uid":"410401601:125:1","speaker":"Urdr","text":"Its balance has been disrupted...\nSurely you too must realize this?","pose":20330207,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"平衡被打破了……你也一定意识到了这一点吧？"}]},{"id":126,"order":126,"actions":[{"uid":"410401601:126:1","speaker":"Kirito","text":"...!","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"...!"},{"uid":"410401601:126:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":127,"order":127,"actions":[{"uid":"410401601:127:1","speaker":"Kirito","text":"...Are you talking about the\nHi-Mobs, and the way the monsters\nsuddenly became more vicious?","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"……你是说Hi-Mobs，以及怪物突然变得更加凶恶的样子吗？"}]},{"id":128,"order":128,"actions":[{"uid":"410401601:128:1","speaker":"Kirito","text":"It's true that there have been\nthings happening that the Cardinal\nSystem couldn't have done before.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"确实发生了卡迪纳尔系统以前做不到的事情。"}]},{"id":129,"order":129,"actions":[{"uid":"410401601:129:1","speaker":"Asuna","text":"So then, Urdr is trying to get rid\nof Alice and Eugeo in order to\nhelp ALO...?","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"那么，乌尔德是想除掉爱丽丝和尤吉欧，以帮助ALO……？"}]},{"id":130,"order":130,"actions":[{"uid":"410401601:130:1","speaker":"Kirito","text":"...But that doesn't mean we can\njust sit back and let her kill our\nfriends!","pose":10011501,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"……但这并不意味着我们就可以坐视她杀死我们的朋友！"}]},{"id":131,"order":131,"actions":[{"uid":"410401601:131:1","speaker":"Kirito","text":"There has to be another way to\nsolve this problem!","pose":10011501,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"必须有别的办法来解决这个问题！"}]},{"id":132,"order":132,"actions":[{"uid":"410401601:132:1","speaker":"Asuna","text":"Yeah... I just can't believe that\nthe world itself is trying to get\nrid of them as \"foreign elements.\"","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"是的……我只是不敢相信这个世界正在试图将他们作为“外来元素”除掉。"}]},{"id":133,"order":133,"actions":[{"uid":"410401601:133:1","speaker":"Kirito","text":"Things are being lost, and this\nworld's whole history is being\nreconstructed...","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"事物正在消失，这个世界的整个历史正在被重建……"}]},{"id":134,"order":134,"actions":[{"uid":"410401601:134:1","speaker":"Kirito","text":"Maybe ALO...","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"也许是ALO……"}]},{"id":135,"order":135,"actions":[{"uid":"410401601:135:1","speaker":"Kirito","text":"the Cardinal System is\nusing Urdr to try and perform a\nmemory defrag.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"卡迪纳尔系统正在使用乌尔德尝试执行内存碎片整理。"}]},{"id":136,"order":136,"actions":[{"uid":"410401601:136:1","speaker":"Asuna","text":"A memory defrag...","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"内存碎片整理..."},{"uid":"410401601:136:2","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":137,"order":137,"actions":[{"uid":"410401601:137:1","speaker":"Urdr","text":"It seems that further discussion\nis pointless. If you mean to\ninterfere, you too shall die...","pose":20330207,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"看来再讨论也没意义了。如果你想干涉的话，你也得死……"}]},{"id":138,"order":138,"actions":[{"uid":"410401601:138:1","speaker":"Asuna","text":"Here she comes, Kirito!","pose":10020901,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"她来了，桐人！"},{"uid":"410401601:138:2","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":139,"order":139,"actions":[{"uid":"410401601:139:1","speaker":"Kirito","text":"Right!","pose":10011501,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"对啊！"}]},{"id":140,"order":140,"actions":[{"uid":"410401601:140:1","speaker":"Kirito","text":"Oof...","pose":10011508,"background":"bg_event_temple","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哎呀……"},{"uid":"410401601:140:2","speaker":"Asuna","text":"","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":141,"order":141,"actions":[{"uid":"410401601:141:1","speaker":"Asuna","text":"I thought we could manage against\njust one of them, but I guess\nnot...","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我以为我们可以对付其中一个，但我想不是……"}]},{"id":142,"order":142,"actions":[{"uid":"410401601:142:1","speaker":"Kirito","text":"Right now, Valkyrie Urdr over\nthere IS a Divine Object.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"现在那边的女武神乌尔德是神器。"}]},{"id":143,"order":143,"actions":[{"uid":"410401601:143:1","speaker":"Kirito","text":"And Divine Objects can alter\nquests, duplicate high-level AI,\npower-up monsters...","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"神器可以改变任务、复制高级AI、强化怪物……"}]},{"id":144,"order":144,"actions":[{"uid":"410401601:144:1","speaker":"Kirito","text":"The only thing that could match\npower formed from a catalyst of\nsuch dense data...","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"只有如此密集的数据催化剂所形成的力量才能匹敌……"}]},{"id":145,"order":145,"actions":[{"uid":"410401601:145:1","speaker":"Kirito","text":"...is another Divine Object.","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"……又是神器。"}]},{"id":146,"order":146,"actions":[{"uid":"410401601:146:1","speaker":"Asuna","text":"Well, that's a problem...","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"嗯，这是个问题……"},{"uid":"410401601:146:2","speaker":"Kirito","text":"","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":147,"order":147,"actions":[{"uid":"410401601:147:1","speaker":"Urdr","text":"Are you ready to die,\nbrave warriors?","pose":20330207,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"勇敢的战士们，你们准备好受死了吗？"}]},{"id":148,"order":148,"actions":[{"uid":"410401601:148:1","speaker":"Kirito","text":"Urdr... I mean, Valkyrie...\nIf your present form and power\ncome from the Divine Objects...","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"乌尔德...我是说，女武神...如果你现在的形态和力量来自神器..."},{"uid":"410401601:148:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":149,"order":149,"actions":[{"uid":"410401601:149:1","speaker":"Kirito","text":"Doesn't that make you all foreign\nelements too?","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"那你们不也都是外国元素吗？"},{"uid":"410401601:149:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":150,"order":150,"actions":[{"uid":"410401601:150:1","speaker":"Urdr","text":"...","pose":20330206,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"..."}]},{"id":151,"order":151,"actions":[{"uid":"410401601:151:1","speaker":"Urdr","text":"Impressive, fairy warriors...\nYou are exactly correct. We gods\nARE born from the Divine Objects.","pose":20330206,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"令人印象深刻，仙女战士们……你说得完全正确。我们神是从神器诞生的。"}]},{"id":152,"order":152,"actions":[{"uid":"410401601:152:1","speaker":"Urdr","text":"And once the other foreign\nelements have been expunged,\nwe too shall leave this world.","pose":20330206,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"一旦其他外来因素被清除，我们也将离开这个世界。"}]},{"id":153,"order":153,"actions":[{"uid":"410401601:153:1","speaker":"Urdr","text":"Thus shall it be cleansed...","pose":20330206,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"这样就可以净化了……"}]},{"id":154,"order":154,"actions":[{"uid":"410401601:154:1","speaker":"Asuna","text":"What?!","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"什么？！"},{"uid":"410401601:154:2","speaker":"Kirito","text":"","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":155,"order":155,"actions":[{"uid":"410401601:155:1","speaker":"???","text":"There you are!","pose":2,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"你来了！"}]},{"id":156,"order":156,"actions":[{"uid":"410401601:156:1","speaker":"Kirito","text":"Huh?!","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"啊？！"}]},{"id":157,"order":157,"actions":[{"uid":"410401601:157:1","speaker":"Alice","text":"Honestly... Why did you leave us\nbehind?","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"老实说……你为什么丢下我们？"},{"uid":"410401601:157:2","speaker":"Eugeo","text":"","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":158,"order":158,"actions":[{"uid":"410401601:158:1","speaker":"Eugeo","text":"Yeah, you're supposed to wake us\nup. We're friends, aren't we?","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"是的，你应该叫醒我们。我们是朋友，不是吗？"}]},{"id":159,"order":159,"actions":[{"uid":"410401601:159:1","speaker":"Asuna","text":"Er, you see... Wait a sec!\nHow did you know where we were?!","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"呃，你看……等一下！你怎么知道我们在哪里？！"},{"uid":"410401601:159:2","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":160,"order":160,"actions":[{"uid":"410401601:160:1","speaker":"Kirito","text":"Never mind that. You two need to\nget out of here! You're the ones\nUrdr is after!","pose":10011501,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"没关系。你们两个必须离开这里！你就是乌尔德所追求的人！"}]},{"id":161,"order":161,"actions":[{"uid":"410401601:161:1","speaker":"Alice","text":"Interesting. That goddess is who\nwe are after as well.","pose":10540104,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"有趣。这位女神也是我们所追求的。"},{"uid":"410401601:161:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":162,"order":162,"actions":[{"uid":"410401601:162:1","speaker":"Alice","text":"I will not bow down and let her\ndispense with us after she tricked\nus into doing her bidding!","pose":10540101,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"她骗我们听话后，我不会低头放过我们！"}]},{"id":163,"order":163,"actions":[{"uid":"410401601:163:1","speaker":"Eugeo","text":"Me neither.","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我也没有。"}]},{"id":164,"order":164,"actions":[{"uid":"410401601:164:1","speaker":"Kirito","text":"I know how strong you two are,\nbut trust me, Urdr is much\nstronger right now!","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我知道你们两个有多强，但是相信我，乌尔德现在更强！"},{"uid":"410401601:164:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":165,"order":165,"actions":[{"uid":"410401601:165:1","speaker":"Kirito","text":"The only way we can hope to match\nher divine strength is with\nanother Divine Object!","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"唯一能匹敌她神力的方法就是再找一个神器！"}]},{"id":166,"order":166,"actions":[{"uid":"410401601:166:1","speaker":"Kirito","text":"...","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"..."}]},{"id":167,"order":167,"actions":[{"uid":"410401601:167:1","speaker":"Kirito","text":"Hang on... The Divine Objects are\nclusters of ultra-dense data...\nWhich means...","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"等一下……神器是超密集数据的集群……这意味着……"}]},{"id":168,"order":168,"actions":[{"uid":"410401601:168:1","speaker":"Asuna","text":"Kirito? What is it?","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"桐人？它是什么？"}]},{"id":169,"order":169,"actions":[{"uid":"410401601:169:1","speaker":"Kirito","text":"Don't tell me... That Alice and\nEugeo are Divine Objects too...?","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"难道爱丽丝和尤吉欧也是神器吗……？"}]},{"id":170,"order":170,"actions":[{"uid":"410401601:170:1","speaker":"Asuna","text":"Huh?!","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"啊？！"}]},{"id":171,"order":171,"actions":[{"uid":"410401601:171:1","speaker":"Alice","text":"Us...? Divine Objects?","pose":10540106,"background":"bg_event_temple","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我们……？ 神器？"},{"uid":"410401601:171:2","speaker":"Eugeo","text":"","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":172,"order":172,"actions":[{"uid":"410401601:172:1","speaker":"Eugeo","text":"What are you saying, Kirito?\nThere's no way we could be\nDivine Objects...","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"桐人你在说什么？我们不可能是神器..."}]},{"id":173,"order":173,"actions":[{"uid":"410401601:173:1","speaker":"Asuna","text":"Wh-What the?!","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"什、什么？！"},{"uid":"410401601:173:2","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":174,"order":174,"actions":[{"uid":"410401601:174:1","speaker":"Kirito","text":"Looks like I was right... That\nmust have been the word we needed\nto finish this puzzle quest.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"看来我是对的……这肯定是我们完成这个谜题任务所需要的单词。"}]},{"id":175,"order":175,"actions":[{"uid":"410401601:175:1","speaker":"Alice","text":"What's going on? How can Eugeo\nand I be Divine Objects?!","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"怎么了？我和尤吉欧怎么可能是神器？！"},{"uid":"410401601:175:2","speaker":"Eugeo","text":"","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":176,"order":176,"actions":[{"uid":"410401601:176:1","speaker":"Eugeo","text":"Look! A Divine Object, right in\nfront of us! Could that be the\nseventh one?!","pose":10530208,"background":"","item":"item_event_sacred_treasure","illustration":"","speaker_zh":"尤吉欧","text_zh":"看！一架神器，就在我们面前！这会是第七个吗？！"}]},{"id":177,"order":177,"actions":[{"uid":"410401601:177:1","speaker":"Kirito","text":"Looks like it... With the other\nsix transformed into gods,\nthis must be the final one.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"看来……其他六人都化神了，这肯定是最后的了。"},{"uid":"410401601:177:2","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":178,"order":178,"actions":[{"uid":"410401601:178:1","speaker":"Asuna","text":"All that time we spent looking,\nand we had it all along...","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我们花了那么多时间寻找，我们一直拥有......"},{"uid":"410401601:178:2","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":179,"order":179,"actions":[{"uid":"410401601:179:1","speaker":"Urdr","text":"Now I understand. The two foreign\nelements are not gods, but humans.\nAlone, they could not contain it.","pose":20330207,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"现在我明白了。这两个外来元素并不是神，而是人。独自一人，他们无法遏制它。"}]},{"id":180,"order":180,"actions":[{"uid":"410401601:180:1","speaker":"Urdr","text":"But by each bearing half,\nthey were able to conceal the\nDivine Object within themselves...","pose":20330207,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"但是通过各持一半，他们能够将神器隐藏在自己体内......"}]},{"id":181,"order":181,"actions":[{"uid":"410401601:181:1","speaker":"Alice","text":"I'm afraid I still fail to\nunderstand... But I do know there\nis one thing we can do now.","pose":10540104,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"恐怕我还是听不懂……但我知道我们现在可以做一件事。"},{"uid":"410401601:181:2","speaker":"Eugeo","text":"","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":182,"order":182,"actions":[{"uid":"410401601:182:1","speaker":"Eugeo","text":"Alice... I was just thinking the\nsame thing.","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"爱丽丝...我也这么想。"}]},{"id":183,"order":183,"actions":[{"uid":"410401601:183:1","speaker":"Kirito","text":"Huh? What do you mean?","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯？你是什​​么意思？"},{"uid":"410401601:183:2","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":184,"order":184,"actions":[{"uid":"410401601:184:1","speaker":"Alice","text":"If we were able to awaken the\nDivine Object, we must also be\nable to wield its power.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"如果我们能够唤醒神器，我们也必须能够运用它的力量。"},{"uid":"410401601:184:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":185,"order":185,"actions":[{"uid":"410401601:185:1","speaker":"Eugeo","text":"Just like the gods of this realm\nused the Objects to make\nthemselves stronger!","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"就像这个境界的神灵通过物品来让自己变得更强一样！"},{"uid":"410401601:185:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":186,"order":186,"actions":[{"uid":"410401601:186:1","speaker":"Urdr","text":"...What?! Impossible!","pose":20330207,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"……什么？！不可能的！"}]},{"id":187,"order":187,"actions":[{"uid":"410401601:187:1","speaker":"Alice","text":"Eugeo, it's time to unlock the\nObject's power! You know what to\ndo, right?!","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"尤吉欧，是时候解锁Object的力量了！你知道该怎么做，对吧？"},{"uid":"410401601:187:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":188,"order":188,"actions":[{"uid":"410401601:188:1","speaker":"Eugeo","text":"You bet!\nEnhance Armament!\nLet's do this, Alice!","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"你打赌！ 武装完全支配术！让我们这样做吧，爱丽丝！"}]},{"id":189,"order":189,"actions":[{"uid":"410401601:189:1","speaker":"Alice","text":"Haaah!!","pose":10540101,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"哈哈哈！！"},{"uid":"410401601:189:2","speaker":"Eugeo","text":"","pose":10530201,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":190,"order":190,"actions":[{"uid":"410401601:190:1","speaker":"Eugeo","text":"Graaah!!","pose":10530201,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"哎呀！！"}]},{"id":191,"order":191,"actions":[{"uid":"410401601:191:1","speaker":"Kirito","text":"That form...!","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"那个形状……！"},{"uid":"410401601:191:2","speaker":"Asuna","text":"","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":192,"order":192,"actions":[{"uid":"410401601:192:1","speaker":"Alice","text":"So this is the Divine Object's\npower...","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"这就是神器的力量……"},{"uid":"410401601:192:2","speaker":"Eugeo","text":"","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":193,"order":193,"actions":[{"uid":"410401601:193:1","speaker":"Eugeo","text":"Incredible! I can feel it surging\nwithin me! There's no way we\ncan lose now!","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"难以置信！我能感觉到它在我体内涌动！现在我们绝对不能输了！"}]},{"id":194,"order":194,"actions":[{"uid":"410401601:194:1","speaker":"Kirito","text":"He's right... Their stats are off\nthe charts...","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"说得对……他们的数据超乎想象的……"},{"uid":"410401601:194:2","speaker":"Asuna","text":"","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":195,"order":195,"actions":[{"uid":"410401601:195:1","speaker":"Urdr","text":"...Very well. I, Valkyrie Urdr,\nshall crush that power with my\nown hands.","pose":20330207,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"……很好。我，女武神乌尔德，将会用我的双手粉碎那股力量。"}]},{"id":196,"order":196,"actions":[{"uid":"410401601:196:1","speaker":"Asuna","text":"Look out, everyone!\nHere she comes!","pose":10020901,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"大家注意啦！她来了！"},{"uid":"410401601:196:2","speaker":"Kirito","text":"","pose":10011501,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":197,"order":197,"actions":[{"uid":"410401601:197:1","speaker":"Kirito","text":"Let's do this!","pose":10011501,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我们开始吧！"},{"uid":"410401601:197:2","speaker":"Asuna","text":"","pose":10020901,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":198,"order":198,"actions":[{"uid":"410401601:198:1","speaker":"Urdr","text":"Guh...","pose":20330206,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"呃……"}]},{"id":199,"order":199,"actions":[{"uid":"410401601:199:1","speaker":"Alice","text":"Now to finish this!","pose":10540101,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"现在就结束吧！"}]},{"id":200,"order":200,"actions":[{"uid":"410401601:200:1","speaker":"Asuna","text":"Alice, don't! She can't fight back\nanymore!","pose":10020901,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"爱丽丝，不要！她已经无力反抗了！"},{"uid":"410401601:200:2","speaker":"Eugeo","text":"","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""},{"uid":"410401601:200:3","speaker":"Kirito","text":"","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":201,"order":201,"actions":[{"uid":"410401601:201:1","speaker":"Alice","text":"Why do you stop me, Asuna?!\nShe used us like pawns, and then\ntried to kill us!","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"亚丝娜你为什么阻止我？！她把我们当作棋子，然后又想杀了我们！"}]},{"id":202,"order":202,"actions":[{"uid":"410401601:202:1","speaker":"Kirito","text":"Forgive her, Alice. I promise you,\nshe wasn't a bad pers...er,\ngoddess to begin with.","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"原谅她吧，爱丽丝。我向你保证，她本来就不是一个坏人……呃，女神。"},{"uid":"410401601:202:2","speaker":"Asuna","text":"","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401601:202:3","speaker":"Eugeo","text":"","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":203,"order":203,"actions":[{"uid":"410401601:203:1","speaker":"Kirito","text":"She was made to do this against\nher will, in order to uphold the\nrules of this world.","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"为了维护这个世界的规则，她被迫这么做。"},{"uid":"410401601:203:2","speaker":"Asuna","text":"","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":204,"order":204,"actions":[{"uid":"410401601:204:1","speaker":"Alice","text":"The rules of this world...\nI...see.","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"这个世界的规则……我……明白了。"}]},{"id":205,"order":205,"actions":[{"uid":"410401601:205:1","speaker":"Urdr","text":"...","pose":20330206,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"..."}]},{"id":206,"order":206,"actions":[{"uid":"410401601:206:1","speaker":"Eugeo","text":"Hey, look! She's changing!","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"嘿，看！她正在改变！"},{"uid":"410401601:206:2","speaker":"Asuna","text":"","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401601:206:3","speaker":"Kirito","text":"","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":207,"order":207,"actions":[{"uid":"410401601:207:1","speaker":"Asuna","text":"Urdr!","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"乌尔德！"},{"uid":"410401601:207:2","speaker":"Kirito","text":"","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":208,"order":208,"actions":[{"uid":"410401601:208:1","speaker":"Urdr","text":"This isn't Jotunheimr...\nWhat am I doing here?","pose":20330106,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"这不是幽兹海姆...我在这里做什么？"}]},{"id":209,"order":209,"actions":[{"uid":"410401601:209:1","speaker":"Kirito","text":"So she's back to her old self?\nAnd it looks like she doesn't\nremember her time as a Valkyrie...","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"她又变回原来的自己了？而且看起来她已经不记得自己作为女武神的时候了……"},{"uid":"410401601:209:2","speaker":"Eugeo","text":"","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""},{"uid":"410401601:209:3","speaker":"Asuna","text":"","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":210,"order":210,"actions":[{"uid":"410401601:210:1","speaker":"Alice","text":"In any case...it seems this battle\nis well and truly over.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"不管怎样……看来这场战斗真的结束了。"}]},{"id":211,"order":211,"actions":[{"uid":"410401601:211:1","speaker":"Urdr","text":"This is...one of the Divine\nObjects? What am I doing with it\nin a place like this?","pose":20330106,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"这是……神物之一？我在这样的地方用它做什么？"}]},{"id":212,"order":212,"actions":[{"uid":"410401601:212:1","speaker":"Eugeo","text":"That's the Divine Object she was\nusing. Good to know things go back\nto normal once you beat them.","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"这就是她所使用的神器。很高兴知道一旦你打败了他们，事情就会恢复正常。"},{"uid":"410401601:212:2","speaker":"Kirito","text":"","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401601:212:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":213,"order":213,"actions":[{"uid":"410401601:213:1","speaker":"Kirito","text":"Yeah. And thanks to you and Alice,\nwe now know how to do just that.\nAlthough...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯。感谢您和爱丽丝，我们现在知道如何做到这一点。虽然..."},{"uid":"410401601:213:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":214,"order":214,"actions":[{"uid":"410401601:214:1","speaker":"Alice","text":"What is it, Kirito?","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"桐人，什么事？"}]},{"id":215,"order":215,"actions":[{"uid":"410401601:215:1","speaker":"Kirito","text":"...Never mind. It's...nothing.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"……没关系。没什么。"},{"uid":"410401601:215:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""},{"uid":"410401601:215:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":216,"order":216,"actions":[{"uid":"410401601:216:1","speaker":"Alice","text":"Kirito, is there something on\nyour mind? If so, then tell us\nwhat it is.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"桐人，你有什么心事吗？如果是这样，请告诉我们它是什么。"}]},{"id":217,"order":217,"actions":[{"uid":"410401601:217:1","speaker":"Kirito","text":"R-Really, it's nothing... Besides,\nright now, we need to hurry and\ntake care of this situation.","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"R、真的，没什么……而且，现在的情况需要赶紧处理。"},{"uid":"410401601:217:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401601:217:3","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":218,"order":218,"actions":[{"uid":"410401601:218:1","speaker":"Asuna","text":"You're right.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"你说得对。"}]}]};
